param([Parameter(Mandatory=$true)][ValidateSet('whole','fla','moe','ck')][string]$Action)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-moe-staged-dot-20260913';$source='D:\projects\AIMA-public-attention-parallel-probability-20260913'
$sha='8a7a8dc5637154d0697427446d6c1576a38b4b6f';$bundle='D:\projects\moe-staged-dot-8a7a8dc.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '83ab4e2ece64419592d2048ec58037ffd140af8939032e9ff1d634f5fea52ff7'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $source fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $source worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$specDir=Join-Path $repo 'build\batch-specs';$null=New-Item -ItemType Directory -Path $specDir -Force
$buildName=$Action;$runTag='r1'
$out=Join-Path $repo ('build\'+$buildName);$recordDir=Join-Path $repo ('build\batch-'+$Action+'-build-'+$runTag);$specPath=Join-Path $specDir ($Action+'-build-'+$runTag+'.json')
foreach($p in @($out,$recordDir,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$exe='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
$sourceInputs=@()
foreach($name in @('native\providers\moe_accumulator\sm121_prefill_projection.h','native\providers\moe_accumulator\sm121_wave16.h','native\providers\moe_accumulator\sm121_lane_reduce.h','native\providers\moe_accumulator\sm121_group16_modulo.h','native\providers\moe_accumulator\q1_moe_hawkeye_bf16_accumulator.h')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable=$exe;working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model='none; native build and component smoke';model_loaded=$false;inference_acceptance=$false;source_inputs=$sourceInputs;sm121_dot_staging_groups=4;purpose=('Build exact DPP routed correction with K64 operand staging: '+$Action)}
switch($Action){
 'whole'{$arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$out,'-CompileTimeoutSeconds','180');$timeout=210}
 'fla'{$arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_fla_gdn.ps1'),'-OutDir',$out,'-AotDir','D:\projects\AIMA-public-capture-20260910\build\fla-r20','-TimeoutSeconds','120');$timeout=160}
 'moe'{
$base='D:\projects\AIMA-public-f544cbed7966\build\runtime-candidate-f544cbe\q8192-moe'
$baseMeta=Join-Path $base 'build-provenance.json'
if((Get-FileHash $baseMeta -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'c8cc58c4af345f2e61d8accb69b8f2eb4c8aa48cbbfa317ae7f6fc39ac61c508'){throw 'Retained MoE build provenance changed'}
$proof=[IO.File]::ReadAllText($baseMeta)|ConvertFrom-Json
foreach($artifact in $proof.artifacts){if((Get-FileHash (Join-Path $base $artifact.file) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact.sha256){throw 'Retained MoE artifact changed'}}

$arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_triton_moe_q8192.ps1'),'-BuildDir',$out,'-OutDir',$out,'-ReuseAotDir',$base,'-HipccPath','C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe','-WslDistribution','Ubuntu-24.04','-WslLlvmStrip','/opt/rocm/llvm/bin/llvm-strip')
$arguments+=@('-BlockM','64','-BlockN','64','-GateBlockN','64','-DownBlockN','64','-GateBlockK','64','-DownBlockK','64','-GroupM','1','-NumWarps','4','-NumStages','1','-WavesPerEu','0','-GateNumWarps','4','-GateNumStages','1','-GateWavesPerEu','0','-DownNumWarps','4','-DownNumStages','1','-DownWavesPerEu','0','-VllmSiluBf16Intermediate','0','-NativeWmmaRouted','0','-RoutedProjectionDebug','0','-BatchedHawkeye','1','-DppReduction','1','-DotStagingGroups','4','-FullSharedHawkeye','0','-ExactShared','0','-ConditionalExactGate','1','-SortedConditionalExactGate','1','-RowMajorSortedConditionalExactGate','1','-ConditionalExactGateRows','256','-ConditionalExactDown','1','-ConditionalExactDownRows','4','-NativeWmmaGate','1','-NativeWmmaDown','1','-NativeFusedRouteLayout','1','-NativeWmmaAdaptiveTail','0','-NativeWmmaBucketedTail','0','-NativeWmmaParallelBucketedTail','0','-NativeWmmaCompactSplitTail','0','-NativeWmmaTail32','0','-NativeWmmaPrune16','0','-NativeWmmaWideN','0','-NativeWmmaLdsB','1','-NativeWmmaLdsBNarrowN','0','-NativeWmmaLdsBM96','0','-NativeWmmaLdsBM64','0','-NativeWmmaLdsBM80LoadWave','0','-NativeWmmaLdsBM80LoadThreads','0','-NativeWmmaLdsBM64LoadThreads','192','-NativeWmmaLdsBM64GateLoadThreads','0','-NativeWmmaLdsBM64DownLoadThreads','0','-NativeWmmaLdsBSplitGatePasses','1','-NativeWmmaLdsBSerialGateN32','1','-NativeWmmaLdsBParallelGateN64','0','-NativeWmmaLdsBParallelGateUpN32','0','-NativeWmmaLdsBSerialDownN32','1','-NativeWmmaLdsBSerialWideN64','0','-NativeWmmaLdsBCompactM96Waves','0','-NativeWmmaLdsBSkipInactiveAStores','1','-NativeWmmaLdsBFusedOverflow16','0','-NativeWmmaLdsBM64FusedOverflow32','1','-NativeWmmaLosslessPalette','1','-NativeWmmaLosslessRowPalette','1','-NativeWmmaWeightInt8','0','-NativeWmmaWeightInt8GroupValues','128','-NativeWmmaWeightInt8ScaleFp16','0','-NativeWmmaLdsBM64DirectM16','0','-NativeWmmaLdsBM64DualM16','0','-NativeWmmaLdsBGroupedSoleM16','0','-NativeWmmaLdsBM64QuadGateM16','0','-NativeWmmaLdsBAdaptiveM128','0','-NativeWmmaLdsBHybridM96M128','0','-NativeWmmaLdsBAdaptiveDirectGrid','0','-NativeWmmaLdsBFullDirectTail','0','-NativeWmmaLdsBCompactSoleTail','0','-NativeWmmaLdsBParallelCompactSoleTail','0','-NativeWmmaTallM96','0','-NativeWmmaKStage','32','-TransposedRouter','1','-RouterThreads','256','-RouterTokenTile','8','-FullV3FusedCombine','1','-FusedCombineWidth','4','-FullV3EventSlots','16','-Repetitions','1','-RequireExpectedFullProviderHash','0')

 $spec.retained_provider_source_sha256=$proof.provider_source_sha256;$spec.retained_provider_commit=$proof.repo_commit;$timeout=240
 }
 'ck'{
 $null=New-Item -ItemType Directory -Path $out -Force
 $ck='D:\projects\composable-kernel-fdf4bb7';$dll=Join-Path $out 'qrt_ck_fmha_sm121.dll'
 $headers=@(Get-ChildItem -LiteralPath $ck -Recurse -File|Where-Object {$_.Extension -in @('.h','.hpp','.cpp')}|Sort-Object FullName|ForEach-Object {@{file=$_.FullName.Substring($ck.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 $headerPath=Join-Path $out 'ck-source-inputs.json';[IO.File]::WriteAllText($headerPath,($headers|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 foreach($name in @('native\providers\ck_fmha\qrt_ck_fmha_q8192_provider.cpp','native\providers\ck_fmha\blackwell_attention.h','native\providers\ck_fmha\fmha_fwd_api.cpp','native\providers\ck_fmha\fmha_fwd_gfx1151_d256_bf16_f32out.cpp','native\providers\gdn\sm121_exp2_table.h','native\providers\gdn\sm121_attention_rcp.h','scripts\baiying_build_ck_fmha_q8192.ps1')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
 $spec.source_inputs=$sourceInputs;$spec.ck_source_manifest_sha256=(Get-FileHash $headerPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.ck_source_files=$headers.Count
 $arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_ck_fmha_q8192.ps1'),'-CkRoot',$ck,'-OutPath',$dll,'-HipccPath','C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe');$timeout=210
 }
}
$spec.arguments=$arguments
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $recordDir -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $recordDir 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($file in @('product.stdout.jsonl','product.stderr.log')){if(Test-Path (Join-Path $recordDir $file)){Get-Content (Join-Path $recordDir $file) -Tail 4|ForEach-Object {$_.Substring(0,[Math]::Min(800,$_.Length))}}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('Native build failed: '+$Action)}
if($Action -eq 'ck'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;ck_source_manifest_sha256=$spec.ck_source_manifest_sha256;ck_source_files=$spec.ck_source_files;command_file=$PSCommandPath;run_record_sha256=(Get-FileHash (Join-Path $recordDir 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();artifact=@{file=$dll;bytes=(Get-Item $dll).Length;sha256=(Get-FileHash $dll -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $out 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}

param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-moe-staged-dot-20260913';$seed='D:\projects\AIMA-public-attention-parallel-probability-20260913'
$sha='8a7a8dc5637154d0697427446d6c1576a38b4b6f';$bundle='D:\projects\moe-staged-dot-8a7a8dc.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '83ab4e2ece64419592d2048ec58037ffd140af8939032e9ff1d634f5fea52ff7'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\staged-dot-safety';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\staged_dot_selftest.cpp';$exe=Join-Path $build 'staged-dot-safety.exe'
$sourceInputs=@();foreach($name in @('tests\native\staged_dot_selftest.cpp','tests\native\scaled_l2_reference.h','native\providers\triton_moe\qrt_triton_moe_q8192_provider.cpp','native\providers\triton_moe\routed_parallel_gate.h','native\providers\moe_accumulator\q1_moe_hawkeye_bf16_accumulator.h','native\providers\moe_accumulator\sm121_wave16.h','native\providers\moe_accumulator\sm121_lane_reduce.h','native\providers\moe_accumulator\sm121_prefill_projection.h','native\providers\moe_accumulator\bf16_scaled_l2.h','native\providers\moe_accumulator\sm121_subgroup.h','native\providers\moe_accumulator\sm121_paired_products.h','native\providers\moe_accumulator\sm121_group16_modulo.h','native\providers\moe_accumulator\sm121_shared_gate.h','native\providers\moe_accumulator\bf16_midpoint_selector.h')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; Staged K16/K64/K128 ordered BF16 dots against the original independent CPU arithmetic, including unaligned input and partial tiles';model_loaded=$false;inference_acceptance=$false}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=120
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@('--selftest');$timeout=90
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\staged-dot-safety-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12|ForEach-Object {$_.Substring(0,[Math]::Min(700,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native safety action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 18){throw 'Missing staged dot safety cases'}
 foreach($report in $reports){if($report.kind -ne 'sm121_staged_dot' -or $report.bit_mismatches -ne 0 -or -not $report.dpp_reduction -or $report.dots -ne 4099){throw 'Staged dot safety failure'}}
}
